message.content:
{
  "gate_token": "7L7OpgyFpurW-daEsukQ5A",
  "title": "The Glass Diver's Map Home",
  "scenes": [
    {
      "scene_number": 1,
      "caption": "Mara unrolls a map of the ruined city at dusk.",
      "visual_description": "A windswept ridge overlooking a half-collapsed royal city, torn banners flapping in the distance; an ink-stained coat flutters as a brass compass spins.",
      "characters": ["mara_the_cartographer"]
    },
    {
      "scene_number": 2,
      "caption": "The oracle lamp warns of false invitations ahead.",
      "visual_description": "An oil lamp held aloft, one glowing eye burning inside its flame, casting orange light over the cracked road into the city.",
      "characters": ["mara_the_cartographer", "oracle_lamp"]
    },
    {
      "scene_number": 3,
      "caption": "The tin fox scouts the outer castle gate.",
      "visual_description": "A small clockwork fox with blue glass eyes crouched beneath an iron portcullis, key-wind tail ticking softly in the moonlight.",
      "characters": ["tin_fox"]
    },
    {
      "scene_number": 4,
      "caption": "Glass Diver arrives by swimming through a tall window.",
      "visual_description": "A figure in a clear diving helmet emerges shoulders-first from a vertical pane of glass set in a ruined wall, coat shimmering with reflected city lanterns.",
      "characters": ["glass_diver"]
    },
    {
      "scene_number": 5,
      "caption": "The team gathers in a collapsed market square.",
      "visual_description": "Broken stalls and overturned carts under a violet sky; a mapmaker, a clockwork fox, a helmeted diver, and a glowing lamp stand together in a tight circle.",
      "characters": ["mara_the_cartographer", "glass_diver", "tin_fox", "oracle_lamp"]
    },
    {
      "scene_number": 6,
      "caption": "A cursed tower glows red, tempting them off course.",
      "visual_description": "A leaning spire pulses with crimson light, runes crawling up its stones; the lamp's eye narrows in distrust.",
      "characters": ["oracle_lamp", "mara_the_cartographer"]
    },
    {
      "scene_number": 7,
      "caption": "They slip past an armored patrol along the wall.",
      "visual_description": "Steel-plated figures march in lockstep along a parapet above; below, the tin fox and the diver press into a shadowed alcove of ivy and rubble.",
      "characters": ["tin_fox", "glass_diver"]
    },
    {
      "scene_number": 8,
      "caption": "Frightened townsfolk whisper of a great winged beast.",
      "visual_description": "Hooded figures peer from boarded windows, pointing skyward at a torn royal banner shaped like a serpent; Mara writes notes by lamp-light.",
      "characters": ["mara_the_cartographer", "oracle_lamp"]
    },
    {
      "scene_number": 9,
      "caption": "The sleeping tax collector blocks a checkpoint.",
      "visual_description": "A plump official slumped over a ledger pillow, stamped papers stuck to his sleeves, snoring beneath a striped boom gate.",
      "characters": ["sleeping_tax_collector", "mara_the_cartographer"]
    },
    {
      "scene_number": 10,
      "caption": "Tin fox lifts the official's keys without waking him.",
      "visual_description": "A delicate metal paw hooks a brass ring of keys from a snoring sleeve; the lamp dims its eye to hide the glow.",
      "characters": ["tin_fox", "sleeping_tax_collector", "oracle_lamp"]
    },
    {
      "scene_number": 11,
      "caption": "Glass Diver dives through a stained window into the keep.",
      "visual_description": "A rippling stained-glass rose distorts as the diver plunges through it like water, coat trailing colored reflections inside a torchlit hall.",
      "characters": ["glass_diver"]
    },
    {
      "scene_number": 12,
      "caption": "A magic door demands a true name to open.",
      "visual_description": "A black iron door inlaid with shifting silver letters; Mara holds her compass to the lock while the lamp leans close, eye flaring.",
      "characters": ["mara_the_cartographer", "oracle_lamp"]
    },
    {
      "scene_number": 13,
      "caption": "Inside, they find the captive bound in mirror chains.",
      "visual_description": "A dim chamber where a slender figure is wrapped in chains made of jointed mirror shards; the diver reaches in through one of the panes.",
      "characters": ["glass_diver", "mara_the_cartographer"]
    },
    {
      "scene_number": 14,
      "caption": "Tin fox triggers an alarm chain by accident.",
      "visual_description": "A clockwork paw catches a tripwire; brass bells cascade down the corridor while blue glass eyes go wide.",
      "characters": ["tin_fox", "glass_diver"]
    },
    {
      "scene_number": 15,
      "caption": "Armored patrols flood the inner courtyard.",
      "visual_description": "Plumed helmets and polearms pour through arches into a moonlit courtyard; the lamp swings violently as Mara sprints, ledger pages flying.",
      "characters": ["mara_the_cartographer", "oracle_lamp"]
    },
    {
      "scene_number": 16,
      "caption": "Glass Diver opens an escape through a fountain pool.",
      "visual_description": "A round fountain glows like a mirror; the diver stands waist-deep, holding out a gloved hand as reflections swirl into a tunnel of light.",
      "characters": ["glass_diver", "tin_fox"]
    },
    {
      "scene_number": 17,
      "caption": "They race across the river bridge at dawn.",
      "visual_description": "A long stone bridge under pink sky, half its arches crumbling into the river; four figures sprint past torn royal banners snapping in the wind.",
      "characters": ["mara_the_cartographer", "glass_diver", "tin_fox", "oracle_lamp"]
    },
    {
      "scene_number": 18,
      "caption": "On the far bank, Mara marks the ruined city closed.",
      "visual_description": "A misty hill beyond the bridge; the mapmaker draws a thick ink line across the city on her map while the lamp's eye softens to gold and the tin fox curls at her boots.",
      "characters": ["mara_the_cartographer", "oracle_lamp", "tin_fox", "glass_diver"]
    }
  ]
}

